export {
  countView,
  fallbackView,
  groupView,
  imageView,
  rootView,
  view,
} from "../avatar";
export type {
  AvatarStyle,
  CountConfig,
  FallbackViewConfig,
  ImageViewConfig,
  RootViewConfig,
  ViewConfig,
} from "../avatar";

export {
  shadcnAvatarBaseClassName,
  shadcnAvatarClassNameBySize,
  shadcnAvatarFallbackClassName,
  shadcnAvatarGroupClassName,
  shadcnAvatarGroupCountClassName,
  shadcnAvatarImageClassName,
  shadcnAvatarSizeClassNameBySize,
} from "./view";
export type { ShadcnAvatarSize } from "./view";

export {
  avatarBaseClassName as shadcnAvatarBaseClassName,
  avatarClassNameBySize as shadcnAvatarClassNameBySize,
  avatarFallbackClassName as shadcnAvatarFallbackClassName,
  avatarGroupClassName as shadcnAvatarGroupClassName,
  avatarGroupCountClassName as shadcnAvatarGroupCountClassName,
  avatarImageClassName as shadcnAvatarImageClassName,
  avatarSizeClassNameBySize as shadcnAvatarSizeClassNameBySize,
} from "../avatar/view";
export type { AvatarSize as ShadcnAvatarSize } from "../avatar/view";

import { describe, expect, test } from "vitest";

import * as Avatar from "./index";

describe("shadcn Avatar registry view", () => {
  test("reuses the Foldkit Avatar view contract", () => {
    expect(Avatar.view).toBeTypeOf("function");
    expect(Avatar.rootView).toBeTypeOf("function");
    expect(Avatar.shadcnAvatarClassNameBySize()).toContain("rounded-full");
  });
});
